(** 0RB0LD_1RC0LA_1LA1RB_0RB1LC *)
(** 0RB0LD_1RC0LA_1LA1RB_0RB1LC -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB0LD_1RC0LA_1LA1RB_0RB1LC : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S0 DL StD
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S0 DL StA
  | StC, S0 => mk S1 DL StA | StC, S1 => mk S1 DR StB
  | StD, S0 => mk S0 DR StB | StD, S1 => mk S1 DL StC end.

(** Its mirror 0LB0RD_1LC0RA_1RA1LB_0LB1RC: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB0LD_1RC0LA_1LA1RB_0RB1LC : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S0 DR StD
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S0 DR StA
  | StC, S0 => mk S1 DR StA | StC, S1 => mk S1 DL StB
  | StD, S0 => mk S0 DL StB | StD, S1 => mk S1 DR StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB0LD_1RC0LA_1LA1RB_0RB1LC : list Instr := [(StA, S0)].
Definition tmw_0RB0LD_1RC0LA_1LA1RB_0RB1LC : TM := tm_wrap_trs tmm_0RB0LD_1RC0LA_1LA1RB_0RB1LC pins_0RB0LD_1RC0LA_1LA1RB_0RB1LC.
