  - (* B0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB0LD_1RC1RA_1LD1RB_1RB1LC (StB, S0)).
    intros p1 j1 E1.
    exact (firex_0RB0LD_1RC1RA_1LD1RB_1RB1LC [SWin 8; SCycL 2 0; SWin 1; SWinL 2] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB0LD_1RC1RA_1LD1RB_1RB1LC
      with (l := [SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB0LD_1RC1RA_1LD1RB_1RB1LC
      with (l := [SCycL 2 0; SWin 4]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB0LD_1RC1RA_1LD1RB_1RB1LC
      with (l := [SCycL 2 0; SWin 4; SCycR 2; SWin 2]).
