Lemma fire_0RB0RB_0LC0RA_1LD1LC_1RA1RC : forall t, ~ In t pins_0RB0RB_0LC0RA_1LD1LC_1RA1RC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
