    by exact lapi_0RB0RB_0LC0RA_1LD1LC_1RA1RC.
  destruct t as [q b]; destruct q, b.
  - (* A0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_0RB0RB_0LC0RA_1LD1LC_1RA1RC
      with (l := [SWin 2; SWin 2; SCycL 4 0; SWin 1; SWinL 2]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_0RB0RB_0LC0RA_1LD1LC_1RA1RC
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB0RB_0LC0RA_1LD1LC_1RA1RC
      with (l := [SWin 2; SWin 2; SCycL 4 0; SWin 1; SWinL 3]).
