    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB0RB_0LC0RA_1LD1LC_1RA1RC
      with (l := [SWin 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB0RB_0LC0RA_1LD1LC_1RA1RC
      with (l := [SWin 2; SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_0RB0RB_0LC0RA_1LD1LC_1RA1RC
      with (l := [SWin 2; SWin 2; SCycL 4 0; SWin 1; SWinL 1]).
    vm_compute; reflexivity.
  - (* D1 *)
