Lemma gsi_0RB0RB_1LC1RA_1LD1RB_0RC0LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_0RB0RB_1LC1RA_1LD1RB_0RC0LC.
