Lemma geo_0RB0RB_1LC1RA_1LD1RB_0RC0LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0RB_1LC1RA_1LD1RB_0RC0LC) = lift (Cc (Pos.succ p)).
