  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB0RB_1LC1RA_1LD1RB_0RC0LC
             = (StB, (rep [S1;S0] (S j) ++ [S1;S1], S0, [S1]))).
  { unfold cden, B1_0RB0RB_1LC1RA_1LD1RB_0RC0LC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S1;S0] (S j) ++ [S1;S1]) ++ [S0], S0, [S1]))).
  { unfold Cc_0RB0RB_1LC1RA_1LD1RB_0RC0LC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_0RB0RB_1LC1RA_1LD1RB_0RC0LC. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_0RB0RB_1LC1RA_1LD1RB_0RC0LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0RB_1LC1RA_1LD1RB_0RC0LC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB0RB_1LC1RA_1LD1RB_0RC0LC B0_0RB0RB_1LC1RA_1LD1RB_0RC0LC B1_0RB0RB_1LC1RA_1LD1RB_0RC0LC 4 12 p j' [] []).
    + exact run_ovf_0RB0RB_1LC1RA_1LD1RB_0RC0LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB0RB_1LC1RA_1LD1RB_0RC0LC p j' E).
    + exact (geo_0RB0RB_1LC1RA_1LD1RB_0RC0LC p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_0RB0RB_1LC1RA_1LD1RB_0RC0LC : stepn tmm_0RB0RB_1LC1RA_1LD1RB_0RC0LC 11 InitES = Some (lift (Cc 1)).
Proof.
