Proof.
  apply (lap_qh_stage tmm_0RB0RB_1LC1RA_1LD1RB_0RC0LC pins_0RB0RB_1LC1RA_1LD1RB_0RC0LC Cc 1 11 32779478).
  - exact bootq_0RB0RB_1LC1RA_1LD1RB_0RC0LC.
  - intros p _. apply lap_0RB0RB_1LC1RA_1LD1RB_0RC0LC.
  - intros t Ht p _. apply fire_0RB0RB_1LC1RA_1LD1RB_0RC0LC. exact Ht.
  - exact wit_0RB0RB_1LC1RA_1LD1RB_0RC0LC.
  - vm_cast_no_check (eq_refl true).
Qed.

Theorem qhtr_0RB0RB_1LC1RA_1LD1RB_0RC0LC : NonHalt tm_0RB0RB_1LC1RA_1LD1RB_0RC0LC /\ QHBoundTr 32779478 tm_0RB0RB_1LC1RA_1LD1RB_0RC0LC /\ QuasiHaltsTr tm_0RB0RB_1LC1RA_1LD1RB_0RC0LC.
