Definition mk_0RB1LA_0LC1RD_1LA1RD_1RC0LA (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_0RB1LA_0LC1RD_1LA1RD_1RC0LA.

(** 0RB1LA_0LC1RD_1LA1RD_1RC0LA *)
(** 0RB1LA_0LC1RD_1LA1RD_1RC0LA -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB1LA_0LC1RD_1LA1RD_1RC0LA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S1 DL StA
  | StB, S0 => mk S0 DL StC | StB, S1 => mk S1 DR StD
  | StC, S0 => mk S1 DL StA | StC, S1 => mk S1 DR StD
  | StD, S0 => mk S1 DR StC | StD, S1 => mk S0 DL StA end.

(** Its mirror 0LB1RA_0RC1LD_1RA1LD_1LC0RA: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB1LA_0LC1RD_1LA1RD_1RC0LA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S1 DR StA
  | StB, S0 => mk S0 DR StC | StB, S1 => mk S1 DL StD
  | StC, S0 => mk S1 DR StA | StC, S1 => mk S1 DL StD
  | StD, S0 => mk S1 DL StC | StD, S1 => mk S0 DR StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB1LA_0LC1RD_1LA1RD_1RC0LA : list Instr := [(StB, S0)].
Definition tmw_0RB1LA_0LC1RD_1LA1RD_1RC0LA : TM := tm_wrap_trs tmm_0RB1LA_0LC1RD_1LA1RD_1RC0LA pins_0RB1LA_0LC1RD_1LA1RD_1RC0LA.
Local Notation tm := tmw_0RB1LA_0LC1RD_1LA1RD_1RC0LA.

Lemma mirror_ok_0RB1LA_0LC1RD_1LA1RD_1RC0LA : mirror_tm tm_0RB1LA_0LC1RD_1LA1RD_1RC0LA = tmm_0RB1LA_0LC1RD_1LA1RD_1RC0LA.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_0RB1LA_0LC1RD_1LA1RD_1RC0LA (p : positive) : cconf := (StD, (Jp p ++ [S0], S0, [S1])).
Local Notation Cc := Cc_0RB1LA_0LC1RD_1LA1RD_1RC0LA.

(** ** The certificate *)

Definition A0_0RB1LA_0LC1RD_1LA1RD_1RC0LA : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S1] [] 0 0 []).
Definition A1_0RB1LA_0LC1RD_1LA1RD_1RC0LA : sconf := mkC StD (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S1;S0] [] 0 0 []).
