Definition cho_0RB1LA_0LC1RD_1LA1RD_1RC0LA : list lstep := [SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 1; SWinR 7; SRotL 2; SFoldL 1].

Lemma run_ovf_0RB1LA_0LC1RD_1LA1RD_1RC0LA : srun tm true true cho_0RB1LA_0LC1RD_1LA1RD_1RC0LA B0_0RB1LA_0LC1RD_1LA1RD_1RC0LA = Some (B1_0RB1LA_0LC1RD_1LA1RD_1RC0LA, 4, 14).
