    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB1LA_1LA1RC_1LA1RD_1RC0LA B0_0RB1LA_1LA1RC_1LA1RD_1RC0LA B1_0RB1LA_1LA1RC_1LA1RD_1RC0LA 4 18 p j' [] []).
    + exact run_ovf_0RB1LA_1LA1RC_1LA1RD_1RC0LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB1LA_1LA1RC_1LA1RD_1RC0LA p j' E).
    + exact (geo_0RB1LA_1LA1RC_1LA1RD_1RC0LA p j' E).
    + lia.
