(** ** The lap *)

Lemma lap_0RB1LA_1LC1RD_0RA1LA_1RB0LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB1LA_1LC1RD_0RA1LA_1RB0LC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB1LA_1LC1RD_0RA1LA_1RB0LC B0_0RB1LA_1LC1RD_0RA1LA_1RB0LC B1_0RB1LA_1LC1RD_0RA1LA_1RB0LC 4 14 p j' [] []).
    + exact run_ovf_0RB1LA_1LC1RD_0RA1LA_1RB0LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB1LA_1LC1RD_0RA1LA_1RB0LC p j' E).
    + exact (geo_0RB1LA_1LC1RD_0RA1LA_1RB0LC p j' E).
    + lia.
Qed.

