  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LA_1LC1RD_0RA1LA_1RB0LC [SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 1; SWinR 3] (StD, S1) ltac:(vm_compute; reflexivity)
