Definition mk_0RB1LA_1LC1RD_1RB1LA_1RB0LC (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_0RB1LA_1LC1RD_1RB1LA_1RB0LC.

(** 0RB1LA_1LC1RD_1RB1LA_1RB0LC *)
(** 0RB1LA_1LC1RD_1RB1LA_1RB0LC -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB1LA_1LC1RD_1RB1LA_1RB0LC : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S1 DL StA
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DR StD
  | StC, S0 => mk S1 DR StB | StC, S1 => mk S1 DL StA
  | StD, S0 => mk S1 DR StB | StD, S1 => mk S0 DL StC end.

(** Its mirror 0LB1RA_1RC1LD_1LB1RA_1LB0RC: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB1LA_1LC1RD_1RB1LA_1RB0LC : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S1 DR StA
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StD
  | StC, S0 => mk S1 DL StB | StC, S1 => mk S1 DR StA
  | StD, S0 => mk S1 DL StB | StD, S1 => mk S0 DR StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB1LA_1LC1RD_1RB1LA_1RB0LC : list Instr := [(StC, S0)].
Definition tmw_0RB1LA_1LC1RD_1RB1LA_1RB0LC : TM := tm_wrap_trs tmm_0RB1LA_1LC1RD_1RB1LA_1RB0LC pins_0RB1LA_1LC1RD_1RB1LA_1RB0LC.
Local Notation tm := tmw_0RB1LA_1LC1RD_1RB1LA_1RB0LC.

Lemma mirror_ok_0RB1LA_1LC1RD_1RB1LA_1RB0LC : mirror_tm tm_0RB1LA_1LC1RD_1RB1LA_1RB0LC = tmm_0RB1LA_1LC1RD_1RB1LA_1RB0LC.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_0RB1LA_1LC1RD_1RB1LA_1RB0LC (p : positive) : cconf := (StD, (Jp p ++ [S0], S0, [S1])).
Local Notation Cc := Cc_0RB1LA_1LC1RD_1RB1LA_1RB0LC.

(** ** The certificate *)

Definition A0_0RB1LA_1LC1RD_1RB1LA_1RB0LC : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S1] [] 0 0 []).
Definition A1_0RB1LA_1LC1RD_1RB1LA_1RB0LC : sconf := mkC StD (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S1;S0] [] 0 0 []).
Definition chi_0RB1LA_1LC1RD_1RB1LA_1RB0LC : list lstep := [SCycL 2 0; SWin 4; SCycR 2; SWin 1; SWinR 7].

Lemma run_int_0RB1LA_1LC1RD_1RB1LA_1RB0LC : srun tm false true chi_0RB1LA_1LC1RD_1RB1LA_1RB0LC A0_0RB1LA_1LC1RD_1RB1LA_1RB0LC = Some (A1_0RB1LA_1LC1RD_1RB1LA_1RB0LC, 4, 12).
Proof. vm_compute. reflexivity. Qed.

Definition B0_0RB1LA_1LC1RD_1RB1LA_1RB0LC : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S0]) S0 (mkS [S1] [] 0 0 []).
Definition B1_0RB1LA_1LC1RD_1RB1LA_1RB0LC : sconf := mkC StD (mkS [] [S1;S1] 1 1 [S1]) S0 (mkS [S1;S0] [] 0 0 []).
Definition cho_0RB1LA_1LC1RD_1RB1LA_1RB0LC : list lstep := [SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 1; SWinR 7; SRotL 2; SFoldL 1].

Lemma run_ovf_0RB1LA_1LC1RD_1RB1LA_1RB0LC : srun tm true true cho_0RB1LA_1LC1RD_1RB1LA_1RB0LC B0_0RB1LA_1LC1RD_1RB1LA_1RB0LC = Some (B1_0RB1LA_1LC1RD_1RB1LA_1RB0LC, 4, 14).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB1LA_1LC1RD_1RB1LA_1RB0LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] j A0_0RB1LA_1LC1RD_1RB1LA_1RB0LC.
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (H1 & _).
  unfold Cc_0RB1LA_1LC1RD_1RB1LA_1RB0LC, cden, A0_0RB1LA_1LC1RD_1RB1LA_1RB0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S1;S0] where the anchor has [S1] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_0RB1LA_1LC1RD_1RB1LA_1RB0LC : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Jp q0 ++ [S0]) [] j A1_0RB1LA_1LC1RD_1RB1LA_1RB0LC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (_ & H2).
  unfold Cc_0RB1LA_1LC1RD_1RB1LA_1RB0LC, cden, A1_0RB1LA_1LC1RD_1RB1LA_1RB0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S1;S0]) with (([S1]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB1LA_1LC1RD_1RB1LA_1RB0LC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (4 * j + 12), (cden (Jp q0 ++ [S0]) [] j A1_0RB1LA_1LC1RD_1RB1LA_1RB0LC).
  split; [lia|]. split; [| exact (gei_0RB1LA_1LC1RD_1RB1LA_1RB0LC p j q0 E)].
  rewrite (gsi_0RB1LA_1LC1RD_1RB1LA_1RB0LC p j q0 E).
  exact (srun_sound tm false true chi_0RB1LA_1LC1RD_1RB1LA_1RB0LC A0_0RB1LA_1LC1RD_1RB1LA_1RB0LC A1_0RB1LA_1LC1RD_1RB1LA_1RB0LC 4 12
           run_int_0RB1LA_1LC1RD_1RB1LA_1RB0LC (Jp q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_0RB1LA_1LC1RD_1RB1LA_1RB0LC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB1LA_1LC1RD_1RB1LA_1RB0LC.
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (H1 & _).
  unfold Cc_0RB1LA_1LC1RD_1RB1LA_1RB0LC, cden, B0_0RB1LA_1LC1RD_1RB1LA_1RB0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB1LA_1LC1RD_1RB1LA_1RB0LC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB1LA_1LC1RD_1RB1LA_1RB0LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1LA_1LC1RD_1RB1LA_1RB0LC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB1LA_1LC1RD_1RB1LA_1RB0LC
             = (StD, (rep [S1;S1] (S j) ++ [S1], S0, ([S1]) ++ [S0]))).
  { unfold cden, B1_0RB1LA_1LC1RD_1RB1LA_1RB0LC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StD, ((rep [S1;S1] (S j) ++ [S1]) ++ [S0], S0, [S1]))).
  { unfold Cc_0RB1LA_1LC1RD_1RB1LA_1RB0LC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lift_app_blank. rewrite !lbl_0RB1LA_1LC1RD_1RB1LA_1RB0LC. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_0RB1LA_1LC1RD_1RB1LA_1RB0LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB1LA_1LC1RD_1RB1LA_1RB0LC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB1LA_1LC1RD_1RB1LA_1RB0LC B0_0RB1LA_1LC1RD_1RB1LA_1RB0LC B1_0RB1LA_1LC1RD_1RB1LA_1RB0LC 4 14 p j' [] []).
    + exact run_ovf_0RB1LA_1LC1RD_1RB1LA_1RB0LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB1LA_1LC1RD_1RB1LA_1RB0LC p j' E).
    + exact (geo_0RB1LA_1LC1RD_1RB1LA_1RB0LC p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_0RB1LA_1LC1RD_1RB1LA_1RB0LC : stepn tmm_0RB1LA_1LC1RD_1RB1LA_1RB0LC 27 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_0RB1LA_1LC1RD_1RB1LA_1RB0LC 27 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_0RB1LA_1LC1RD_1RB1LA_1RB0LC 27 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_0RB1LA_1LC1RD_1RB1LA_1RB0LC : existsb (fun tg => cfires tmm_0RB1LA_1LC1RD_1RB1LA_1RB0LC c0 27 tg) pins_0RB1LA_1LC1RD_1RB1LA_1RB0LC = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB1LA_1LC1RD_1RB1LA_1RB0LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB1LA_1LC1RD_1RB1LA_1RB0LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB1LA_1LC1RD_1RB1LA_1RB0LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB1LA_1LC1RD_1RB1LA_1RB0LC p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB1LA_1LC1RD_1RB1LA_1RB0LC : forall t, ~ In t pins_0RB1LA_1LC1RD_1RB1LA_1RB0LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_0RB1LA_1LC1RD_1RB1LA_1RB0LC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LA_1LC1RD_1RB1LA_1RB0LC [SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 1; SWinR 1] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LA_1LC1RD_1RB1LA_1RB0LC [SCycL 2 0; SWin 2; SWinL 3] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LA_1LC1RD_1RB1LA_1RB0LC [SCycL 2 0; SWin 2; SWinL 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LA_1LC1RD_1RB1LA_1RB0LC [SCycL 2 0; SWin 1] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LA_1LC1RD_1RB1LA_1RB0LC [SCycL 2 0; SWin 2; SWinL 2] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LA_1LC1RD_1RB1LA_1RB0LC [] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LA_1LC1RD_1RB1LA_1RB0LC [SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 1; SWinR 3] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem qhtrm_0RB1LA_1LC1RD_1RB1LA_1RB0LC : NonHalt tmm_0RB1LA_1LC1RD_1RB1LA_1RB0LC /\ QHBoundTr 32779478 tmm_0RB1LA_1LC1RD_1RB1LA_1RB0LC /\ QuasiHaltsTr tmm_0RB1LA_1LC1RD_1RB1LA_1RB0LC.
Proof.
  apply (lap_qh_stage tmm_0RB1LA_1LC1RD_1RB1LA_1RB0LC pins_0RB1LA_1LC1RD_1RB1LA_1RB0LC Cc 1 27 32779478).
  - exact bootq_0RB1LA_1LC1RD_1RB1LA_1RB0LC.
  - intros p _. apply lap_0RB1LA_1LC1RD_1RB1LA_1RB0LC.
  - intros t Ht p _. apply fire_0RB1LA_1LC1RD_1RB1LA_1RB0LC. exact Ht.
  - exact wit_0RB1LA_1LC1RD_1RB1LA_1RB0LC.
  - vm_cast_no_check (eq_refl true).
Qed.

Theorem qhtr_0RB1LA_1LC1RD_1RB1LA_1RB0LC : NonHalt tm_0RB1LA_1LC1RD_1RB1LA_1RB0LC /\ QHBoundTr 32779478 tm_0RB1LA_1LC1RD_1RB1LA_1RB0LC /\ QuasiHaltsTr tm_0RB1LA_1LC1RD_1RB1LA_1RB0LC.
Proof. apply (qh_triple_unmirror 32779478 tm_0RB1LA_1LC1RD_1RB1LA_1RB0LC). rewrite mirror_ok_0RB1LA_1LC1RD_1RB1LA_1RB0LC. exact qhtrm_0RB1LA_1LC1RD_1RB1LA_1RB0LC. Qed.

